// Generate topic ideas from RAG knowledge base
const topics = [
  {
    query: "ancient KMT wisdom and teachings",
    title: "Ancient KMT Wisdom Series"
  },
  {
    query: "metu neter principles and cosmology",
    title: "Metu Neter Cosmology"
  },
  {
    query: "matrix of power and control systems",
    title: "Matrix of Power Analysis"
  },
  {
    query: "RBG library historical perspectives",
    title: "RBG Historical Perspectives"
  }
];

// Select a random topic or use the first one
const selectedTopic = topics[Math.floor(Math.random() * topics.length)];

return {
  json: {
    query: selectedTopic.query,
    title: selectedTopic.title,
    timestamp: new Date().toISOString()
  }
};

// Extract RAG response and prepare for scene generation
const ragResponse = $input.item.json;
const topic = $('Generate Topic').item.json;

// Extract answer and sources from RAG
const answer = ragResponse.answer || '';
const sources = ragResponse.sources || [];

// Create prompt for scene generation
const scenePrompt = `Based on this knowledge from our RAG system:

${answer}

Generate 10 detailed video scenes for a longform video titled: "${topic.title}"

Each scene should include:
- Scene number (1-10)
- Visual description
- Narration/prompts
- Duration estimate (in seconds)
- Visual style notes

Format as a numbered list with clear scene breaks.`;

return {
  json: {
    title: topic.title,
    mainContent: answer,
    sources: sources.map(s => ({
      file: s.file_name,
      page: s.page,
      preview: s.preview
    })),
    query: topic.query,
    scenePrompt: scenePrompt
  }
};

// Parse Ollama response and structure scenes
const ollamaResponse = $input.item.json;
const context = $('Prepare Scene Generation').item.json;

// Extract text from Ollama response
const responseText = ollamaResponse.response || ollamaResponse.text || JSON.stringify(ollamaResponse);

// Try to parse scenes from response
let scenes = [];

try {
  // Try to find numbered scenes
  const sceneMatches = responseText.match(/Scene \d+[\s\S]*?(?=Scene \d+|$)/gi);

  if (sceneMatches && sceneMatches.length > 0) {
    scenes = sceneMatches.slice(0, 10).map((match, idx) => ({
      id: idx + 1,
      description: match.trim(),
      title: `Scene ${idx + 1}`
    }));
  } else {
    // Split by common delimiters
    const parts = responseText.split(/\n\n|\n(?=\d+\.|Scene)/).filter(p => p.trim());
    const scenesPerPart = Math.max(1, Math.floor(parts.length / 10));

    scenes = Array.from({ length: 10 }, (_, i) => {
      const startIdx = i * scenesPerPart;
      const endIdx = Math.min((i + 1) * scenesPerPart, parts.length);
      const content = parts.slice(startIdx, endIdx).join('\n\n');

      return {
        id: i + 1,
        description: content.trim() || `Scene ${i + 1} content`, 
        title: `Scene ${i + 1}`
      };
    });
  }
} catch (e) {
  // Fallback: create 10 scenes from response
  const chunkSize = Math.ceil(responseText.length / 10);
  scenes = Array.from({ length: 10 }, (_, i) => ({
    id: i + 1,
    description: responseText.substring(i * chunkSize, (i + 1) * chunkSize).trim(),
    title: `Scene ${i + 1}`
  }));
}

return {
  json: {
    title: context.title,
    scenes: scenes,
    ragSources: context.sources,
    aspectRatio: "16:9",
    productionStatus: "Concept Development",
    timestamp: new Date().toISOString()
  }
};

// Prepare image generation prompts from scene data
const scene = $input.item.json;
const title = $('Parse Scenes').first().json.title;

// Extract visual description from scene
const sceneDescription = scene.description || scene.visual || scene.content || '';

// Create image prompt (limit to 500 chars for API)
const imagePrompt = `Cinematic vlog style: ${sceneDescription.substring(0, 500)}. Hyperrealistic, natural lighting, handheld camera aesthetic, earthy tones, misty atmosphere, documentary style.`;

return {
  json: {
    sceneId: scene.id || scene.sceneId,
    sceneTitle: scene.title || `Scene ${scene.id}`,
    imagePrompt: imagePrompt,
    videoPrompt: scene.description || sceneDescription,
    title: title,
    aspectRatio: "16:9"
  }
};

// Extract image URLs from response
const response = $input.item.json;
const sceneData = $('Prepare Image Prompts').item.json;

// Handle different response formats
let imageUrl = '';
if (response.images && response.images.length > 0) {
  imageUrl = response.images[0].src || response.images[0].url || response.images[0];
} else if (response.src) {
  imageUrl = response.src;
} else if (response.url) {
  imageUrl = response.url;
} else if (Array.isArray(response) && response.length > 0) {
  imageUrl = response[0].src || response[0].url || response[0];
} else if (typeof response === 'string') {
  imageUrl = response;
}

return {
  json: {
    ...sceneData,
    imageUrl: imageUrl,
    imageReference: imageUrl
  }
};

// Prepare video creation request
const sceneData = $input.item.json;

// Create video generation payload
return {
  json: {
    ...sceneData,
    videoType: "longform",
    duration: 60,
    style: "cinematic vlog"
  }
};

// Aggregate all video segments
const videos = $input.all();

return {
  json: {
    videos: videos.map(v => v.json),
    totalVideos: videos.length
  }
};

// Log completion
const videoData = $input.item.json;
const title = $('Parse Scenes').first().json.title;

return {
  json: {
    status: "completed",
    title: title,
    videoUrl: videoData.url || videoData.video_url || "N/A",
    timestamp: new Date().toISOString(),
    message: `Video '${title}' successfully generated from RAG knowledge base and uploaded.`
  }
};
